import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/DIS.DdpTdGGD.js";import{_ as o,o as t,c as n,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"Li3","description":"","frontmatter":{"source_hash":"a98504fa65","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/install/li3.md","filePath":"it/install/li3.md"}'),r={name:"it/install/li3.md"};function l(c,e,p,d,u,m){return t(),n("div",null,[...e[0]||(e[0]=[s('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Li3</p></div><p>La sorgente dati Li3, aggiunta nella release <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer">2026.11.21</a>, collega xDrip direttamente a un dispositivo Li3. Puoi selezionarla anche con la <a href="./datasource.html">procedura guidata della sorgente dati</a>, nel gruppo Libre.</p><p>xDrip avvia una nuova sessione, o prende il controllo di una sessione in corso, con una scansione NFC. Poi riceve le letture tramite Bluetooth.</p><ul><li>Le letture arrivano ogni 5 minuti, oppure ogni minuto se è attivata l&#39;opzione <a href="./../use/misc.html">Libre one minute</a>.</li><li>Quando la connessione torna dopo un&#39;interruzione, xDrip completa le letture mancanti con la cronologia del dispositivo. Le letture già registrate non vengono mai sostituite.</li><li><strong>Questa sorgente dati non può essere calibrata.</strong> Se ci provi, xDrip mostra <em>This sensor cannot be calibrated.</em> (questo sensore non può essere calibrato)</li></ul><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Quando xDrip avvia o prende il controllo di una sessione, l&#39;app ufficiale smette di ricevere le letture e gli allarmi.</p></div><br><h2 id="before-you-start" tabindex="-1">Prima di iniziare <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Prima di iniziare {#before-you-start}&quot;">​</a></h2><ul><li>Il telefono deve avere l&#39;NFC. Senza NFC, xDrip mostra <em>This phone has no NFC, so it cannot start a Li3.</em> (questo telefono non ha l&#39;NFC, quindi non può avviare un Li3)</li><li>Attiva l&#39;NFC nelle impostazioni del telefono. Se la scansione NFC di xDrip è disattivata, xDrip propone di attivarla.</li><li>xDrip ha bisogno dell&#39;autorizzazione alla posizione, e la localizzazione deve essere attiva, per cercare il dispositivo via Bluetooth. La schermata Li3 chiede tutto ciò che manca.</li><li>Ti serve una connessione a internet una volta, per scaricare la credenziale dell&#39;app.</li><li>Se non l&#39;hai ancora fatto, <a href="./install.html#make-sure-xdrip-will-not-be-put-to-sleep">verifica che xDrip non venga messo in sospensione</a>.</li></ul><br><h2 id="the-li3-screen" tabindex="-1">La schermata Li3 <a class="header-anchor" href="#the-li3-screen" aria-label="Permalink to &quot;La schermata Li3 {#the-li3-screen}&quot;">​</a></h2><p>La schermata Li3 elenca i passaggi della configurazione, mostra a che punto sei e legge le scansioni NFC mentre è aperta.<br> Si apre da sola quando selezioni la sorgente dati Li3 e quando tocchi Inizializza Sensore senza che nessun sensore sia avviato. Puoi aprirla anche da Stato del sistema:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Stato del sistema<br>  Li3 Status<br>   Li3  Open</p></div><p>Finché la configurazione non è terminata, xDrip mostra anche una notifica che apre questa schermata: <em>Li3 setup not finished; open System Status, Li3</em> (configurazione Li3 non terminata; apri Stato del sistema, Li3).</p><p>Se scansioni il dispositivo mentre è aperta un&#39;altra schermata, xDrip apre la schermata Li3 e ti chiede di scansionarlo di nuovo lì: <em>Scan the device again on the Li3 screen to start it or take it over</em> (scansiona di nuovo il dispositivo nella schermata Li3 per avviarlo o prenderne il controllo).</p><br><h2 id="setup" tabindex="-1">Configurazione <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Configurazione {#setup}&quot;">​</a></h2><h4 id="1-download-the-app-credential" tabindex="-1">1. Scaricare la credenziale dell&#39;app <a class="header-anchor" href="#1-download-the-app-credential" aria-label="Permalink to &quot;1. Scaricare la credenziale dell&#39;app {#1-download-the-app-credential}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  DOWNLOAD APP CREDENTIAL </div></p></div><p>Il dispositivo si abbina con una credenziale dell&#39;app. Se non ne è ancora stata scaricata nessuna, xDrip propone di scaricarla quando apri la schermata Li3.<br> Al termine, la riga App credential sotto i pulsanti mostra <em>Downloaded</em> (scaricata). Se il download non riesce, controlla la connessione a internet e tocca di nuovo Download.</p><h4 id="2-account-id-only-to-take-over-a-session-started-by-an-official-app" tabindex="-1">2. Account ID (solo per prendere il controllo di una sessione avviata da un&#39;app ufficiale) <a class="header-anchor" href="#2-account-id-only-to-take-over-a-session-started-by-an-official-app" aria-label="Permalink to &quot;2. Account ID (solo per prendere il controllo di una sessione avviata da un&#39;app ufficiale) {#2-account-id-only-to-take-over-a-session-started-by-an-official-app}&quot;">​</a></h4><p>Salta questo passaggio per avviare una nuova sessione per xDrip.</p><p>Per prendere il controllo di una sessione avviata da un&#39;app ufficiale, xDrip ha bisogno dell&#39;account ID di quell&#39;app.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  LOOK UP ACCOUNT ID </div></p></div><p>Accedi con l&#39;account che ha avviato la sessione, non con un account follower. xDrip conserva solo l&#39;account ID, non l&#39;email né la password.<br> Se l&#39;accesso viene rifiutato a causa di nuove condizioni d&#39;uso, apri l&#39;app ufficiale con questo account, accetta le condizioni e poi riprova.<br> Se la ricerca non riesce, puoi inserire tu stesso l&#39;account ID nelle <a href="#li3-settings">impostazioni Li3</a>.</p><p>Poi scegli l&#39;app che ha avviato la sessione:</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  SENSOR APP: LI3 APP </div></p></div><div class="admonition xdripitem"><p class="admonition-title">Which app started this session?</p><p> Li3 app<br>  Multi-sensor app</p></div><h4 id="3-scan-the-device" tabindex="-1">3. Scansionare il dispositivo <a class="header-anchor" href="#3-scan-the-device" aria-label="Permalink to &quot;3. Scansionare il dispositivo {#3-scan-the-device}&quot;">​</a></h4><p>Con la schermata Li3 aperta, scansiona il dispositivo con il telefono. xDrip ti pone una di queste domande:</p><table tabindex="0"><thead><tr><th>Dispositivo</th><th>Account ID impostato</th><th>Nessun account ID</th></tr></thead><tbody><tr><td>Nuovo</td><td><strong>Start Sensor</strong>: xDrip riceve le letture. L&#39;app ufficiale può riprendere il dispositivo in seguito con lo stesso account.</td><td><strong>Start Sensor</strong>: la sessione è per xDrip solo su questo telefono. <strong>Il dispositivo non potrà mai passare a un&#39;app ufficiale e andrà perso se reinstalli xDrip.</strong></td></tr><tr><td>Sessione in corso</td><td><strong>Take over Li3</strong>: l&#39;app ufficiale smette di ricevere le letture e gli allarmi.</td><td>Funziona solo per una sessione avviata da xDrip su questo telefono. Per una sessione avviata da un&#39;app ufficiale, cerca prima il suo account ID.</td></tr></tbody></table><p>Senza account ID, puoi toccare <em>Look up account ID</em> oppure <em>Scan anyway</em> per proseguire senza.</p><p>Premi Ok, poi <strong>scansiona di nuovo il dispositivo entro cinque minuti</strong> per confermare.<br> Quando funziona, xDrip mostra <em>Li3 ready, connecting by Bluetooth</em> (Li3 pronto, connessione via Bluetooth).</p><p>Se il dispositivo rifiuta il comando, controlla che l&#39;app e l&#39;account ID siano quelli con cui è stata avviata la sessione.<br> Se xDrip usa già questo dispositivo, non viene inviato nulla. Per abbinarlo di nuovo, tocca Dimentica questo dispositivo nella schermata Li3, poi scansionalo.</p><h4 id="4-wait-for-the-first-reading" tabindex="-1">4. Attendere la prima lettura <a class="header-anchor" href="#4-wait-for-the-first-reading" aria-label="Permalink to &quot;4. Attendere la prima lettura {#4-wait-for-the-first-reading}&quot;">​</a></h4><p>Un dispositivo nuovo non invia letture durante più o meno la prima ora.</p><br><h2 id="li3-settings" tabindex="-1">Impostazioni Li3 <a class="header-anchor" href="#li3-settings" aria-label="Permalink to &quot;Impostazioni Li3 {#li3-settings}&quot;">​</a></h2><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>   Impostazioni Meno Usate<br>    Altre opzioni<br>     Li3</p></div><div class="admonition xdripitem"><p class="admonition-title">Account ID</p><p> Needed to take over a session in progress. Leave empty to start a new session for xDrip on this phone only.</p></div><p>Look up account ID, nella schermata Li3, lo compila per te.</p><div class="admonition xdripitem"><p class="admonition-title">Official app</p><p> The app the account uses</p></div><p>Li3 app (predefinita) o Multi-sensor app. È la stessa scelta del pulsante Sensor app nella schermata Li3.</p><div class="admonition xdripitem"><p class="admonition-title">Smooth Li3 readings <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Average recent readings to make them smoother</p></div><p>Le impostazioni NFC che non si applicano a Li3 (età del sensore, giorni di scadenza, multiblocco, any tag, streaming Bluetooth Libre 2) sono nascoste mentre Li3 è la sorgente dati.</p><br><h2 id="status" tabindex="-1">Stato <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Stato {#status}&quot;">​</a></h2><p>La schermata Li3 e Stato del sistema → Li3 Status mostrano:</p><ul><li><strong>Device</strong> (dispositivo)</li><li><strong>Stage</strong> (fase): cosa sta facendo xDrip in quel momento, ad esempio: <ul><li><em>No device; scan one with NFC</em> (nessun dispositivo; scansionane uno con l&#39;NFC)</li><li><em>No app credential; tap Download on the Li3 screen</em> (nessuna credenziale dell&#39;app; tocca Download nella schermata Li3)</li><li><em>Looking for the device; keep the phone near it</em> (ricerca del dispositivo; tieni il telefono vicino)</li><li><em>Lost the device; trying again soon</em> (dispositivo perso; nuovo tentativo a breve)</li><li><em>Connected; waiting for a reading</em> (connesso; in attesa di una lettura)</li><li><em>Session ended; scan a new device with NFC</em> (sessione terminata; scansiona un nuovo dispositivo con l&#39;NFC)</li></ul></li><li><strong>Last error</strong> (ultimo errore)</li><li><strong>Reading not stored</strong> (lettura non registrata), quando xDrip ha rifiutato una lettura: nessun valore valido, l&#39;ora di inizio della sessione sembra sbagliata, oppure il dispositivo ha segnalato la lettura come inaffidabile</li><li><strong>Started</strong> (avviato) e <strong>Sensor life</strong> (durata del sensore) (oppure <em>Expired</em>, scaduto)</li><li><strong>Last reading</strong> (ultima lettura)</li><li><strong>App credential</strong> (credenziale dell&#39;app)</li></ul><h4 id="forget-device" tabindex="-1">Dimenticare il dispositivo <a class="header-anchor" href="#forget-device" aria-label="Permalink to &quot;Dimenticare il dispositivo {#forget-device}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  DIMENTICA QUESTO DISPOSITIVO </div></p></div><p>xDrip smette di comunicare con questo dispositivo. Per usarlo di nuovo, scansionalo con l&#39;NFC.<br> Una sessione avviata senza account può tornare solo a xDrip su questo telefono.</p><h4 id="copy-diagnostics" tabindex="-1">Copiare la diagnostica <a class="header-anchor" href="#copy-diagnostics" aria-label="Permalink to &quot;Copiare la diagnostica {#copy-diagnostics}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  COPY DIAGNOSTICS </div></p></div><p>Copia le informazioni di diagnostica negli appunti. Incollale quando chiedi aiuto.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 22/11/2026</em></a></p>',56)])])}const b=o(r,[["render",l]]);export{f as __pageData,b as default};
